SELECT artb_temp.company_id, artb_temp.customer_id, artb_temp.invoice_no, artb_temp.total_amount, artb_temp.memo_amount, CAST(CONVERT(VarChar(11), artb_temp.invoice_date, 113) AS DateTime) 'invoice_date', artb_temp.salesrep_name, artb_temp.total_receipts, artb_temp.allowed_amount, artb_temp.salesrep_id, artb_temp.order_date, artb_temp.order_no, artb_temp.date_created, artb_temp.date_last_modified, artb_temp.last_maintained_by, artb_temp.period, artb_temp.year_for_period, company.company_name, artb_temp.terms_desc, artb_temp.bad_debt_amount, artb_temp.terms_amount, artb_temp.net_due_date, address_a.mail_address1, NULLIF(address_a.mail_address2,''), ISNULL(address_a.mail_city,''), ISNULL(address_a.mail_state,''), ISNULL(address_a.mail_postal_code,''), address_a.central_phone_number, address_b.name, address_b.mail_address1, NULLIF(address_b.mail_address2,''), ISNULL(address_b.mail_city,''), ISNULL(address_b.mail_state,''), ISNULL(address_b.mail_postal_code,''), address_b.central_phone_number, CASE 'B' WHEN 'I' THEN ''ELSE artb_temp.branch_idEND AS branch_id, branch.branch_description,artb_temp.po_no,artb_temp.invoice_class,address_b.corp_address_id,customer.generate_statements_by,address_c.name,address_c.mail_address1,NULLIF(address_c.mail_address2,''),ISNULL(address_c.mail_city,''),ISNULL(address_c.mail_state,''),ISNULL(address_c.mail_postal_code,''),address_c.central_phone_number,customer.print_zero_dollar_customers,CAST({ts '2020-11-16 15:41:07.281'} AS datetime) statement_date,'N' group_by_credits,NULLIF(address_a.mail_country, ''),NULLIF(address_b.mail_country, ''),NULLIF(address_c.mail_country, ''),currency_hdr.currency_desc,CASE artb_temp.record_type_cdWHEN 2594 THEN artb_temp.record_type_reference_noELSE ''END original_rebilled_invoice_no,artb_temp.tax_terms_taken_amt,NULLIF(address_a.mail_address3,'') ,NULLIF(address_b.mail_address3,'') ,NULLIF(address_c.mail_address3,'')FROM p21_fnt_artb(2021005, '1', 'Y', '0', '99999999', 0, '11/16/2020 15:41:07', 'N', 10297, 10297) artb_temp INNER JOIN company ON (company.company_id = artb_temp.company_id)INNER JOIN branch ON (branch.company_id = artb_temp.company_id ) AND(branch.branch_id = artb_temp.branch_id)INNER JOIN customer ON (customer.company_id = artb_temp.company_id) AND(customer.customer_id = artb_temp.customer_id)INNER JOIN address AS address_a ON (address_a.id = company.address_id)INNER JOIN address AS address_b ON (address_b.id = artb_temp.customer_id)	INNER JOIN address AS address_c ON (address_b.corp_address_id = address_c.id)INNER JOIN invoice_batch ON invoice_batch.invoice_batch_uid = artb_temp.statement_batch_uid	LEFT JOIN currency_hdr ON currency_hdr.currency_id = customer.currency_idLEFT JOIN currency_line ON currency_line.currency_line_uid = artb_temp.currency_line_uidWHERE (customer.open_item_balance_forward = 'O' ) AND(artb_temp.total_receipts <> ((total_amount + memo_amount + bad_debt_amount) - allowed_amount - terms_amount - tax_terms_taken_amt)) AND customer.generate_customer_statements = 'Y'AND invoice_batch.invoice_batch_number BETWEEN 0 AND 9999AND ( NULL IS NULL	OR currency_line.to_currency_id IS NULLOR COALESCE(currency_line.to_currency_id, 1) = 1)AND ( ( artb_temp.branch_id BETWEEN '100' AND '100' )OR ( artb_temp.branch_id IS NULL )) AND artb_temp.date_created BETWEEN {ts '1990-01-01 00:00:00.000'} AND {ts '2049-12-31 00:00:00.000'}AND artb_temp.date_last_modified BETWEEN {ts '1990-01-01 00:00:00.000'} AND {ts '2049-12-31 00:00:00.000'}AND artb_temp.last_maintained_by BETWEEN ' ' AND 'ZZZZZZZ'AND artb_temp.approved = 'Y'AND ('A' = 'A' OR ('G' = 'A' AND 'ID' = 'ID' AND {ts '2020-11-16 15:41:07.281'} >= DATEADD(day, 0, artb_temp.invoice_date)) OR ('G' = 'A' AND 'ID' = 'DD' AND {ts '2020-11-16 15:41:07.281'} >= DATEADD(day, 0, artb_temp.net_due_date)))AND ('Y' = 'Y' OR ('N' = 'Y' AND artb_temp.invoice_adjustment_type <> 'C'))AND ('Y' = 'Y' OR ('N' = 'Y' AND artb_temp.invoice_class <> 'Z'))/* Print all invoices if customers have at least one past due or past invoice date */AND (('N' = 'N') OR (artb_temp.customer_id IN (	SELECT artb_past_date.customer_idFROM p21_fnt_artb(2021005, '1', 'Y', '0', '99999999', 0, '11/16/2020 15:41:07', 'N', 10297, 10297) artb_past_dateWHERE (artb_past_date.total_receipts <> ((artb_past_date.total_amount+ artb_past_date.memo_amount+ artb_past_date.bad_debt_amount)- artb_past_date.allowed_amount- artb_past_date.terms_amount))AND (artb_past_date.approved = 'Y')	AND artb_past_date.customer_id = artb_temp.customer_idAND ((('ID' = 'ID') AND {ts '2020-11-16 15:41:07.281'} >= Dateadd(day, 0, artb_past_date.invoice_date))OR (('ID' = 'DD') AND {ts '2020-11-16 15:41:07.281'} >= Dateadd(day, 0, artb_past_date.net_due_date) ))GROUP BY artb_past_date.customer_id) ))	